    def separateSquares(self, squares: List[List[int]]) -> float:
        def get_areas(y_line):
            below = 0.0
            above = 0.0

            for x, y_bottom, l in squares:
                y_top = y_bottom + l

                if y_line >= y_top:
                    below += l * l
                elif y_line <= y_bottom:
                    above += l * l
                else:
                    height_below = y_line - y_bottom
                    height_above = y_top - y_line
                    below += l * height_below
                    above += l * height_above

            return below, above

        total_area = sum(l * l for x, y, l in squares)
        target_below = total_area / 2.0

        left, right = 0.0, float(max(y + l for x, y, l in squares))

        for _ in range(100):
            mid = (left + right) / 2.0
            below, above = get_areas(mid)

            if below < target_below:
                left = mid
            else:
                right = mid

        return (left + right) / 2.0

