class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def manhattan(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        def can_select(min_dist):
            def backtrack(index, selected):
                if len(selected) == k:
                    return True
                if index == len(points):
                    return False

                if len(selected) + (len(points) - index) < k:
                    return False

                if all(manhattan(points[index], points[i]) >= min_dist for i in selected):
                    if backtrack(index + 1, selected + [index]):
                        return True

                if backtrack(index + 1, selected):
                    return True

                return False

            return backtrack(0, [])

        left, right = 0, 2 * side
        while left < right:
            mid = (left + right + 1) // 2
            if can_select(mid):
                left = mid
            else:
                right = mid - 1

        return left

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def manhattan(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        def can_select(min_dist):
            for start_idx in range(len(points)):
