            evens = list(range(2, max_val + 1, 2))
            odds = list(range(1, max_val + 1, 2))

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(i1, i2, e_idx, o_idx, last1, last2):
                if i1 == n1 and i2 == n2:
                    return True

                can_do = False

                # Try processing nums1[i1] next
