                            if evens[ej] > last1:
                                if dp(i1 + 1, i2, ej + 1, o_idx, evens[ej], last2):
                                    can_do = True
                                    break
                    else:
                        for oj in range(o_idx, len(odds)):
                            if odds[oj] > last1:
                                if dp(i1 + 1, i2, e_idx, oj + 1, odds[oj], last2):
                                    can_do = True
                                    break

