class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        prefix, middle, suffix = parts[0], parts[1], parts[2]

        min_len = float('inf')

        for start in range(len(s)):
            if not s[start:].startswith(prefix):
                continue

            after_prefix = start + len(prefix)

            if middle:
                middle_pos = s.find(middle, after_prefix)
                if middle_pos == -1:
                    continue
                after_middle = middle_pos + len(middle)
            else:
                after_middle = after_prefix

            if suffix:
                suffix_pos = s.find(suffix, after_middle)
                if suffix_pos == -1:
                    continue
                end = suffix_pos + len(suffix)
            else:
                end = after_middle

            min_len = min(min_len, end - start)

        return min_len if min_len != float('inf') else -1

