        n = len(nums)
        # dp[i][last_diff] = longest subsequence ending at index i with last difference = last_diff
        # Use float('inf') to represent the start of a sequence (no previous difference)
        dp = [{} for _ in range(n)]

        # Initialize: each element can start a sequence
        for i in range(n):
            dp[i][float('inf')] = 1

        ans = 1

        # For each pair (i, j) where i < j
        for i in range(n):
            for j in range(i + 1, n):
                new_diff = abs(nums[j] - nums[i])

                # Try to extend subsequences ending at i
                for last_diff, length in dp[i].items():
                    # Can extend if last_diff >= new_diff (non-increasing constraint)
                    if last_diff >= new_diff:
                        if new_diff not in dp[j]:
                            dp[j][new_diff] = length + 1
                        else:
                            dp[j][new_diff] = max(dp[j][new_diff], length + 1)
                        ans = max(ans, dp[j][new_diff])

        return ans

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        # dp[i] is a dictionary where dp[i][diff] = max length of subsequence ending at i with last diff
        dp = [dict() for _ in range(n)]

        for i in range(n):
            # Start a new subsequence at i (length 1)
            dp[i][float('inf')] = 1  # No previous difference

            # Extend from previous positions
            for j in range(i):
                diff = abs(nums[i] - nums[j])
                for prev_diff, length in dp[j].items():
                    # Only extend if previous difference >= current difference (non-increasing)
                    if prev_diff >= diff:
                        dp[i][diff] = max(dp[i].get(diff, 0), length + 1)

        # Find maximum length across all positions
        ans = 0
        for i in range(n):
            ans = max(ans, max(dp[i].values()))
        return ans

