class Solution:
    def maxSizedArray(self, s: int) -> int:
        def count_bit_set(n, bit):
            period = 1 << (bit + 1)
            full_periods = n // period
            remainder = n % period
            count = full_periods * (1 << bit)
            if remainder > (1 << bit):
                count += remainder - (1 << bit)
            return count

        def sum_or(n):
            total = 0
            for bit in range(60):
                if (1 << bit) >= n:
                    break
                count = count_bit_set(n, bit)
                contribution = (1 << bit) * count * (2 * n - count)
                total += contribution
            return total

        def total_sum(n):
            so = sum_or(n)
            return so * n * (n - 1) // 2

        left, right = 1, 10**6
        while left < right:
            mid = (left + right + 1) // 2
            if total_sum(mid) <= s:
                left = mid
            else:
                right = mid - 1

        return left

