    def maxSizedArray(self, s: int) -> int:
        def compute_sum(n):
            if n == 0:
                return 0

            i_sum = n * (n - 1) // 2

            or_sum = 0
            for b in range(20):
                power = 1 << b
                double_power = 1 << (b + 1)
                count_not_b = (n // double_power) * power + min(n % double_power, power)
                count_b = n * n - count_not_b * count_not_b
                or_sum += power * count_b

            return i_sum * or_sum

        left, right = 1, 2000
        result = 1

        while left <= right:
            mid = (left + right) // 2
            total = compute_sum(mid)
            if total <= s:
                result = mid
                left = mid + 1
            else:
                right = mid - 1

        return result

