class Solution:
    def findSubtreeSizes(self, parent: List[int], s: str) -> List[int]:
        n = len(parent)

        # For each node, find new parent by locating closest ancestor with same character
        new_parent = [-1] * n

        for x in range(1, n):
            # Traverse ancestors to find closest with matching character
            y = parent[x]
            while y != -1 and s[y] != s[x]:
                y = parent[y]

            if y != -1:
                new_parent[x] = y  # Found matching ancestor
            else:
                new_parent[x] = parent[x]  # No match, keep original parent

        # Build new tree with updated parent relationships
        new_children = [[] for _ in range(n)]
        for i in range(1, n):
            new_children[new_parent[i]].append(i)

        # Compute subtree sizes via DFS
        sizes = [0] * n

        def dfs(node):
            sizes[node] = 1
            for child in new_children[node]:
                sizes[node] += dfs(child)
            return sizes[node]

        dfs(0)

        return sizes

