    def findSubtreeSizes(self, parent: List[int], s: str) -> List[int]:
        n = len(parent)

        # Build the original tree
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Find new parent for each node
        new_parent = [-1] * n

        def dfs(node, char_to_ancestor):
            # Find new parent for this node
            if s[node] in char_to_ancestor:
                new_parent[node] = char_to_ancestor[s[node]]
            else:
                new_parent[node] = parent[node] if node != 0 else -1

            # Add current node as ancestor for its children
            old_val = char_to_ancestor.get(s[node], None)
            char_to_ancestor[s[node]] = node

            # Process children
            for child in children[node]:
                dfs(child, char_to_ancestor)

            # Restore
            if old_val is None:
                del char_to_ancestor[s[node]]
            else:
                char_to_ancestor[s[node]] = old_val

        dfs(0, {})

        # Build new tree
        new_children = [[] for _ in range(n)]
        for i in range(1, n):
            new_children[new_parent[i]].append(i)

        # Compute subtree sizes in the new tree
        sizes = [0] * n

        def dfs_size(node):
            sizes[node] = 1
            for child in new_children[node]:
                sizes[node] += dfs_size(child)
            return sizes[node]

        dfs_size(0)

        return sizes

